    normalized = str(raw_value).strip()
    normalized = re.sub(r"^[（(]\s*如有\s*[)）]\s*", "", normalized)
    normalized = re.sub(r"^[（(]\s*if\s+any\s*[)）]\s*", "", normalized, flags=re.IGNORECASE)
    normalized = re.sub(r"[ \t　]+", " ", normalized)
    return normalized


