def _has_explicit_multi_steps(question: str):
    """判断题目是否包含显式多步骤要求。"""
    step_markers = re.findall(r"[①②③④⑤⑥⑦⑧⑨⑩]|\d+\.", question or "")
    clause_count = len(
        [item for item in re.split(r"[；;。]\s*|\n+", question or "") if item.strip()]
    )
    return len(step_markers) >= 3 or clause_count >= 3


