    doc.chunk_status = models_knowledge_document.CHUNK_STATUS_PROCESSING
    commit_or_rollback(db)

    return schemas_knowledge_base.ChunkSubmitResponse(
        document_id=document_id,
        status="processing",
        message="切块任务已提交",
    )


