def clean_pdf_text(raw: str):
    """清洗 PDF 提取文本"""
    text = raw.strip()
    text = re.sub(r"[ \t]+", " ", text)
    text = re.sub(r"\n{3,}", "\n\n", text)
    return text.strip()


