def _extract_where_clause(sql: str):
    """从 SQL 中提取 WHERE 子句"""
    match = re.search(
        r"(?is)\bWHERE\b(?P<where>.*?)(?=\bORDER\s+BY\b|\bGROUP\s+BY\b|\bLIMIT\b|$)",
        sql,
    )
    return match.group("where") if match else ""


def _extract_order_by_clause(sql: str):
